    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr\">P = x</span><sup>2</sup><span dir=\"ltr\" class=\"expr\"> − 6x − 2</span>"},{"quoi":"القاعدة","math":"إكمال المربّع <span dir=\"ltr\" class=\"expr\">: x</span><sup>2</sup> <span dir=\"ltr\" class=\"expr\">− 2ax = (x − a)</span><sup>2</sup> <span dir=\"ltr\" class=\"expr\">− a</span><sup>2</sup>"},{"quoi":"نطبّق","math":"نصف معامل <span dir=\"ltr\" class=\"expr\">x</span> هو <span dir=\"ltr\" class=\"expr\">3</span> ، إذن <span dir=\"ltr\" class=\"expr\">P = (x − 3)</span><sup>2</sup> <span dir=\"ltr\" class=\"expr\">− 9 − 2</span>  أي  <span dir=\"ltr\" class=\"expr\">P = (x − 3)</span><sup>2</sup> <span dir=\"ltr\" class=\"expr\">− 11</span>"},{"quoi":"القاعدة","math":"إذا كان <span dir=\"ltr\" class=\"expr\">(x − a)</span><sup>2</sup> <span dir=\"ltr\" class=\"expr\">= k</span> و <span dir=\"ltr\" class=\"expr\">k &gt; 0</span> فإنّ <span dir=\"ltr\" class=\"expr\">x = a − √k</span> أو <span dir=\"ltr\" class=\"expr\">x = a + √k</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr\">(x − 3)</span><sup>2</sup> <span dir=\"ltr\" class=\"expr\">= 11</span>  إذن  <span dir=\"ltr\" class=\"expr\">x − 3 = −√11</span>  أو  <span dir=\"ltr\" class=\"expr\">x − 3 = √11</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">S = { 3 − √11 ; 3 + √11 }</span>"}],
